/**
 * Pionier service worker
 * Generated by scripts/sync-handpan-cache.mjs — do not hand-edit.
 * Bump handpan-app/APP_VERSION then run: npm run sync:handpan
 *
 * Strategy:
 *  - HTML / navigations: network-first (fallback to cached index)
 *  - Hashed assets (./assets/*): cache-first, immutable
 *  - Other same-origin GET: cache-first, then network
 *  - On activate: drop all caches except current CACHE_VERSION
 */

const CACHE_VERSION = 'pionier-v210';

const ASSETS = [
  './assets/app-C7UilF0n.css',
  './assets/app-CSZfdJmD.js',
  './assets/audio-core-BKBAUavA.js',
  './assets/fx-editor-Ib0mot0D.js',
  './assets/handpan-D4MvzjUi.js',
  './assets/handpan-DvBPp9R-.js',
  './assets/library-BV1ko3Fb.js',
  './assets/loop-core-D1b8JEmO.js',
  './assets/master-clock-CG8N4kNY.js',
  './assets/note-plus-Cc8DzZ59.js',
];

const HTML_SHELL = ['.', './index.html'];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_VERSION);
    // Pre-cache hashed assets (immutable, cache-first)
    let failed = [];
    await Promise.all(ASSETS.map(async (url) => {
      try {
        const res = await fetch(url, { cache: 'no-cache' });
        if (res && res.ok) await cache.put(url, res); else failed.push(url);
      } catch (_) { failed.push(url); }
    }));
    if (failed.length > 0) console.warn('[sw] precache skipped:', failed.join(', '));
    await self.skipWaiting();
  }));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k !== CACHE_VERSION).map((k) => caches.delete(k)));
    await self.clients.claim();
  }));
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // HTML / navigations: network-first, cache fallback
  const isDoc =
    req.mode === 'navigate' ||
    req.destination === 'document' ||
    url.pathname.endsWith('.html') ||
    url.pathname.endsWith('/') ||
    url.pathname.endsWith('/handpan-app');

  if (isDoc) {
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (res && res.ok) {
            const copy = res.clone();
            caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});
          }
          return res;
        })
        .catch(() => caches.match(req).then((r) => r || caches.match('./index.html')))
    );
    return;
  }

  // Hashed assets: cache-first, immutable
  const isAsset = url.pathname.startsWith('/assets/');
  if (isAsset) {
    event.respondWith(
      caches.match(req).then((cached) => {
        if (cached) return cached;
        return fetch(req).then((res) => {
          if (res && res.status === 200 && res.type !== 'opaque') {
            const copy = res.clone();
            caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});
          }
          return res;
        });
      })
    );
    return;
  }


  // Other same-origin GET: cache-first, then network
  event.respondWith(
    caches.match(req).then((cached) => {
      if (cached) return cached;
      return fetch(req).then((res) => {
        if (res && res.status === 200 && res.type !== 'opaque') {
          const copy = res.clone();
          caches.open(CACHE_VERSION).then((c) => c.put(req, copy)).catch(() => {});
        }
        return res;
        });
      })
    );
  });
